<?php
if(!defined('ABSPATH'))exit;
function bsktv_feature_box(){add_meta_box('bsktv_flags','推薦設定','bsktv_feature_render','post','side','default');}add_action('add_meta_boxes','bsktv_feature_box');
function bsktv_feature_render($post){wp_nonce_field('bsktv_feature_save','bsktv_feature_nonce');echo '<p><label><input type="checkbox" name="bsktv_featured" value="1" '.checked(get_post_meta($post->ID,'bsktv_featured',true),'1',false).'> 編輯推薦</label></p><p><label><input type="checkbox" name="bsktv_home_featured" value="1" '.checked(get_post_meta($post->ID,'bsktv_home_featured',true),'1',false).'> 首頁推薦</label></p>';}function bsktv_feature_save($id){if(!isset($_POST['bsktv_feature_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsktv_feature_nonce'])),'bsktv_feature_save'))return;if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE)return;if(wp_is_post_revision($id)||!current_user_can('edit_post',$id))return;update_post_meta($id,'bsktv_featured',isset($_POST['bsktv_featured'])?'1':'0');update_post_meta($id,'bsktv_home_featured',isset($_POST['bsktv_home_featured'])?'1':'0');}add_action('save_post_post','bsktv_feature_save');
